**Интерфейс MemoryLayer (ABC)**

```python
from abc import ABC, abstractmethod

class MemoryLayer(ABC):
    @abstractmethod
    def remember(self, content: str, **kwargs) -> None:
        """Запомнить контент в памяти."""

    @abstractmethod
    def recall(self, query: str, **kwargs) -> list[dict]:
        """Получить данные из памяти по запросу."""

    @abstractmethod
    def clear(self, **kwargs) -> None:
        """Очистить всю память."""
```

**Интерфейс MemoryManager**

```python
from typing import List

class MemoryManager:
    def __init__(self):
        self.layers: List[MemoryLayer] = []

    def add_layer(self, layer: MemoryLayer) -> None:
        """Добавить слой памяти."""
        self.layers.append(layer)

    def remove_layer(self, layer: MemoryLayer) -> None:
        """Удалить слой памяти."""
        self.layers.remove(layer)

    def remember(self, content: str, **kwargs) -> None:
        """Запомнить контент во всех слоях."""
        for layer in self.layers:
            layer.remember(content, **kwargs)

    def recall(self, query: str, **kwargs) -> List[dict]:
        """Получить данные из всех слоев по запросу."""
        results = []
        for layer in self.layers:
            results.extend(layer.recall(query, **kwargs))
        return results

    def clear(self, **kwargs) -> None:
        """Очистить все слои памяти."""
        for layer in self.layers:
            layer.clear(**kwargs)
```

**Пример реализации ShortTermMemory**

```python
class ShortTermMemory(MemoryLayer):
    def __init__(self, capacity: int = 100):
        self.capacity = capacity
        self.data = []

    def remember(self, content: str, **kwargs) -> None:
        if len(self.data) >= self.capacity:
            self.data.pop(0)
        self.data.append({"content": content, "timestamp": datetime.now()})

    def recall(self, query: str, **kwargs) -> List[dict]:
        return [item for item in self.data if query.lower() in item["content"].lower()]

    def clear(self, **kwargs) -> None:
        self.data.clear()
```

